CREATE TABLE IF NOT EXISTS exercise_scan_codes (
  code text PRIMARY KEY CHECK (code ~ '^[A-Z0-9:_-]{4,64}$'),
  exercise_id uuid NOT NULL REFERENCES exercises (id) ON DELETE CASCADE,
  manufacturer_id text REFERENCES equipment_manufacturers (id) ON DELETE SET NULL,
  code_kind text NOT NULL CHECK (code_kind IN ('traina', 'model')),
  label text NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS exercise_scan_codes_exercise_idx ON exercise_scan_codes (exercise_id);

